"""Summarize workflow tables without changing the node."""
import argparse
from datetime import datetime, timedelta, timezone
import json
from pathlib import Path
import re

EVERY = re.compile(r"[1-9][0-9]*[rsmhd]\Z")
CODE = re.compile(r"[+-]?[0-9]+\Z")
SECONDS = {"s": 1, "m": 60, "h": 3600, "d": 86400}
REQUIRED = {"routines": ("name", "every", "last_time", "last_code"),
            "schedule": ("name", "at", "claimed")}


def reject_constant(value):
    raise ValueError("non-finite JSON number: " + value)


def table(node, name, bad):
    try:
        with (node / "wf" / (name + ".json")).open(encoding="utf-8") as stream:
            value = json.load(stream, parse_constant=reject_constant)
    except FileNotFoundError:
        return []
    except (OSError, UnicodeError, ValueError):
        bad.append({"table": name, "row": None, "why": "bad_table"})
        return []
    if (not isinstance(value, dict) or value.get("contract") != "wf-table/1"
            or not isinstance(value.get("columns"), list)
            or not all(isinstance(column, str) for column in value["columns"])
            or not isinstance(value.get("rows"), list)):
        bad.append({"table": name, "row": None, "why": "bad_table"})
        return []
    return value["rows"]


def timestamp(value, now):
    result = datetime.fromisoformat(value)
    return result.replace(tzinfo=now.tzinfo) if result.tzinfo is None else result


def routine(row, now):
    every = row["every"]
    if not EVERY.fullmatch(every):
        raise ValueError("invalid interval")
    last = row["last_time"]
    when = timestamp(last, now) if last else None
    text = row["last_code"]
    if text == "":
        code = None
    elif text == "running":
        code = "running"
    elif CODE.fullmatch(text):
        code = int(text)
    else:
        raise ValueError("invalid exit code")
    following = None
    deadline = None
    if when is not None and every[-1] != "r":
        deadline = when + timedelta(seconds=int(every[:-1]) * SECONDS[every[-1]])
        following = deadline.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    if code == "running":
        state = "running"
    elif when is None:
        state = "never"
    elif isinstance(code, int) and code != 0:
        state = "failed"
    elif deadline is not None and now >= deadline:
        state = "overdue"
    else:
        state = "ok"
    return {"name": row["name"], "every": every,
            "last_time": last if last else None, "last_code": code,
            "state": state, "next": following}


def scheduled(row, now):
    at = timestamp(row["at"], now)
    state = "interrupted" if row["claimed"] else "due" if at <= now else "pending"
    return {"name": row["name"], "at": row["at"], "state": state}


def summarize(node, now):
    bad = []
    output = {"v": 1, "routines": [], "schedule": [],
              "counts": {"routines": dict.fromkeys(
                  ("running", "never", "failed", "overdue", "ok"), 0),
                         "schedule": dict.fromkeys(("interrupted", "due", "pending"), 0)},
              "bad": bad}
    for name in ("routines", "schedule"):
        seen = set()
        for index, row in enumerate(table(node, name, bad)):
            candidate = row.get("name") if isinstance(row, dict) else None
            if isinstance(candidate, str) and candidate:
                if candidate in seen:
                    bad.append({"table": name, "row": index, "why": "dup_name"})
                    continue
                seen.add(candidate)
            if (not isinstance(row, dict) or not isinstance(candidate, str)
                    or not candidate or any(not isinstance(value, str) for value in row.values())
                    or any(field not in row for field in REQUIRED[name])):
                bad.append({"table": name, "row": index, "why": "bad_row"})
                continue
            try:
                item = routine(row, now) if name == "routines" else scheduled(row, now)
            except (ValueError, OverflowError):
                bad.append({"table": name, "row": index, "why": "bad_row"})
                continue
            output[name].append(item)
            output["counts"][name][item["state"]] += 1
        output[name].sort(key=lambda item: item["name"])
    bad.sort(key=lambda item: (item["table"], -1 if item["row"] is None else item["row"], item["why"]))
    return output


def main(argv=None):
    parser = argparse.ArgumentParser(description="Summarize workflow tables read-only")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    if not args.folder.is_dir():
        parser.error("folder is not a directory")
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO datetime with a timezone")
    if now.tzinfo is None:
        parser.error("--now must have a timezone")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=True, allow_nan=False,
                     separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

