"""Temporary-node helpers for CLI tests."""
import json
from pathlib import Path
import subprocess
import sys

ENTRY = Path(__file__).resolve().parents[1] / "bin" / "aos7-runs"
NOW = "2025-01-02T00:00:00+00:00"


def write_table(node, name, rows, columns=None):
    wf = node / "wf"
    wf.mkdir(exist_ok=True)
    (wf / (name + ".json")).write_text(json.dumps({
        "contract": "wf-table/1", "columns": [] if columns is None else columns,
        "rows": rows}), encoding="utf-8")


def run(node, *extra):
    return subprocess.run([sys.executable, str(ENTRY), str(node), *extra],
                          capture_output=True, text=True, check=False)


def routine(name, every="1s", last_time="", last_code=""):
    return {"name": name, "every": every, "last_time": last_time,
            "last_code": last_code}
